import 'package:cloud_firestore/cloud_firestore.dart';
class Saving { final String id, memberId; final double amount; final DateTime date; const Saving({required this.id, required this.memberId, required this.amount, required this.date}); factory Saving.fromMap(String id, Map<String,dynamic> m)=>Saving(id:id, memberId:m['memberId']??'', amount:(m['amount']??0).toDouble(), date:(m['date'] as Timestamp?)?.toDate()??DateTime.now()); Map<String,dynamic> toMap()=>{'memberId':memberId,'amount':amount,'date':Timestamp.fromDate(date)}; @override String toString()=> 'TZS $amount saved by $memberId'; }
